import { aesOpen, aesSeal, bytesToHex, hexToBytes } from '../crypto.js'
import type { KeyName, KeyStore } from './types.js'

const STORE = 'kv'

function req<T>(r: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    r.onsuccess = () => resolve(r.result)
    r.onerror = () => reject(r.error)
  })
}

/**
 * Browser key store (default in browsers / Tauri). A non-extractable AES-GCM key is generated by
 * WebCrypto and persisted in IndexedDB as a CryptoKey object: JavaScript can use it but can never
 * read its bytes. All secrets are stored sealed with it.
 *
 * Protects against: database/disk theft, other origins. Does NOT protect against: script running
 * in your origin (XSS) using the key while the page is open.
 */
export function browserKeyStore(name = 'anodb'): KeyStore {
  if (typeof indexedDB === 'undefined') throw new Error('anoDB: browserKeyStore needs IndexedDB')
  const dbp = (async () => {
    const open = indexedDB.open(`${name}-keys`, 1)
    open.onupgradeneeded = () => open.result.createObjectStore(STORE)
    return req(open)
  })()
  const tx = async (mode: IDBTransactionMode) => (await dbp).transaction(STORE, mode).objectStore(STORE)
  const wrapping = (async () => {
    const existing = (await req((await tx('readonly')).get('wrapping-key'))) as CryptoKey | undefined
    if (existing) return existing
    const key = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt'])
    await req((await tx('readwrite')).put(key, 'wrapping-key'))
    return key
  })()
  return {
    kind: 'browser',
    async get(n: KeyName) {
      const v = (await req((await tx('readonly')).get(n))) as string | undefined
      if (!v) return null
      return new TextDecoder().decode(await aesOpen(await wrapping, hexToBytes(v)))
    },
    async set(n: KeyName, value: string) {
      const sealed = await aesSeal(await wrapping, new TextEncoder().encode(value))
      await req((await tx('readwrite')).put(bytesToHex(sealed), n))
    },
    async remove(n: KeyName) {
      await req((await tx('readwrite')).delete(n))
    },
    seal: async (p) => aesSeal(await wrapping, p),
    open: async (s) => aesOpen(await wrapping, s),
  }
}
